const baseCourses=[...courses];
const defaults={name:'Engineering Student',email:'',role:'student',progress:{},completed:[],startedCourses:[],bookmarks:[],activity:[],attempts:{},enrolled:[],assignments:[],meetings:[],customCourses:[],planner:[],notes:[],flashcards:[],settings:{theme:'light'}};
let db={...defaults},view='Overview',filter='All courses',quizState=null,chatLog=[],authMode='login',selectedRole='student',readerText='Welcome to your engineering reading space. Open a course resource or upload a text file to begin. Your reading progress is saved to your account.',flashSession=[],flashIndex=0,flashRevealed=false;
let saveQueue=Promise.resolve();
function save(){const {name,...data}=db;saveQueue=saveQueue.then(()=>fetch('/api/data',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({...data,name})})).then(async r=>{if(!r.ok)throw Error((await r.json()).error||'Could not save account data.')}).catch(e=>toast(e.message||'Could not save. Check your connection and sign in again.'));}
function allCourses(){return [...courses,...(db.customCourses||[])].filter(c=>!['circuits','thermo'].includes(c.id))}
async function loadCatalog(){try{const r=await fetch('/api/courses',{cache:'no-store'});if(!r.ok)return;const data=await r.json(),deleted=new Set(data.deleted||[]),overrides=data.overrides||{};courses=baseCourses.filter(c=>!deleted.has(c.id)).map(c=>overrides[c.id]?{...c,...overrides[c.id]}:c);courses.push(...(data.created||[]).filter(c=>!courses.some(base=>base.id===c.id)))}catch{}}
function enrolledIds(){return [...new Set((db.enrolled||[]).flatMap(id=>id==='circuits'?['ml']:id==='thermo'?['ai']:[id]))]}
function isEnrolled(id){return enrolledIds().includes(id)}
function prepareUser(user){const next={...defaults,...user};next.enrolled=[...new Set((next.enrolled||[]).flatMap(id=>id==='circuits'?['ml']:id==='thermo'?['ai']:[id]))];const starterIds=new Set(['circuits','thermo','dsa','ml','ai','math','calc','physics','electronics']);const emptyStudy=(next.activity||[]).length===0&&Object.keys(next.progress||{}).length===0&&Object.keys(next.attempts||{}).length===0;if(emptyStudy&&next.enrolled.length>0&&next.enrolled.every(id=>starterIds.has(id)))next.enrolled=[];return next}
function toast(msg){const t=document.getElementById('toast');if(!t)return;t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}
function applyReadableDashboardTheme(){
  if(document.getElementById('vinedu-readable-theme'))return;
  const style=document.createElement('style');style.id='vinedu-readable-theme';style.textContent=`
    :root{--ui-ink:#173b32;--ui-muted:#637a70;--ui-green:#247b60;--ui-line:#e1eae4;--ui-canvas:#f5f8f5}
    body{color:var(--ui-ink);background:var(--ui-canvas);font-size:15px;line-height:1.6;-webkit-font-smoothing:antialiased}
    button,input,select,textarea{font:inherit}
    :focus-visible{outline:3px solid #82c4a5;outline-offset:3px}
    aside,.sidebar,[class*=sidebar]{background:#fff;border-right:1px solid var(--ui-line)}
    main{min-width:0}
    h1,h2,h3{color:#15382f;line-height:1.22;letter-spacing:-.025em}
    p,label,small{line-height:1.65}
    input,select,textarea{border:1px solid #d9e5dd;border-radius:12px;padding:11px 14px}
    button{transition:transform .16s ease,box-shadow .16s ease,background-color .16s ease}
    button:hover{transform:translateY(-1px)}
    @media(max-width:760px){body{font-size:14px}aside,.sidebar,[class*=sidebar]{max-width:100%;border-right:0}}
  `;document.head.appendChild(style)
}
applyReadableDashboardTheme();
function vineduOpenSettingsFromProfile(){const nav=[...document.querySelectorAll('aside a,aside button,.sidebar a,.sidebar button,nav a,nav button,[role=link]')].find(el=>/\bsettings\b/i.test(el.textContent.trim()));if(nav){nav.click();return}if(typeof window.go==='function'){window.go('settings');return}const any=[...document.querySelectorAll('a,button')].find(el=>/\bsettings\b/i.test(el.textContent.trim()));any?.click()}
function vineduFixProfileActions(){document.querySelectorAll('[data-vinedu-profile-launch]').forEach(button=>button.style.setProperty('display','none','important'));document.querySelectorAll('.vinedu-profile-edit,[data-edit-profile]').forEach(button=>{if(button.dataset.vineduEditBound)return;button.dataset.vineduEditBound='1';button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();document.querySelectorAll('.vinedu-profile-view-card').forEach(el=>el.remove());vineduOpenSettingsFromProfile()},{capture:true})})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>{vineduFixProfileActions();new MutationObserver(vineduFixProfileActions).observe(document.body,{childList:true,subtree:true})},{once:true});else{vineduFixProfileActions();new MutationObserver(vineduFixProfileActions).observe(document.body,{childList:true,subtree:true})}
if(!document.getElementById('vinedu-profile-actions-fix')){const style=document.createElement('style');style.id='vinedu-profile-actions-fix';style.textContent='[data-vinedu-profile-launch]{display:none!important}';document.head.appendChild(style)}
function vineduForceFullDarkContrast(){const mode=[document.documentElement.dataset.theme,document.body?.dataset.theme,document.documentElement.className,document.body?.className].join(' ').toLowerCase();const sun=[...document.querySelectorAll('header button,.topbar button,[class*=topbar] button')].some(el=>/☀/.test(el.textContent));const roots=[document.body,...document.querySelectorAll('main,#app,[id*=app],[class*=app-shell],[class*=workspace],[class*=main-content]')].filter(Boolean);const darkSurface=roots.some(el=>{const color=getComputedStyle(el).backgroundColor;if(!color||color==='transparent'||/rgba\([^)]*,\s*0(?:\.0+)?\s*\)$/.test(color))return false;const values=color.match(/[\d.]+/g)?.map(Number)||[];return values.length>=3&&values[0]*.2126+values[1]*.7152+values[2]*.0722<105});const dark=/dark/.test(mode)||sun||darkSurface;if(!dark){document.body?.removeAttribute('data-vinedu-dark-contrast');document.querySelectorAll('[data-vinedu-contrast-text]').forEach(el=>{el.style.removeProperty('color');delete el.dataset.vineduContrastText});document.querySelectorAll('[data-vinedu-contrast-surface]').forEach(el=>{el.style.removeProperty('background-color');el.style.removeProperty('border-color');delete el.dataset.vineduContrastSurface});return}document.body?.setAttribute('data-vinedu-dark-contrast','true');const surfaces='aside,header,main,.sidebar,.topbar,[class*=sidebar],[class*=topbar],.card,.panel,[class*=card],[class*=panel],[class*=surface],[role=dialog],article,.vinedu-header-popover';document.querySelectorAll(surfaces).forEach(el=>{el.dataset.vineduContrastSurface='1';el.style.setProperty('background-color','#192c23','important');el.style.setProperty('border-color','#3a5144','important')});const texts='h1,h2,h3,h4,h5,h6,p,small,label,legend,li,a,span,strong,b,[class*=title],[class*=name],[class*=heading]';document.querySelectorAll(texts).forEach(el=>{if(el.closest('.vinedu-course-cover'))return;el.dataset.vineduContrastText='1';el.style.setProperty('color','#f3f7f4','important')});document.querySelectorAll('input,select,textarea').forEach(el=>{el.style.setProperty('background-color','#12231c','important');el.style.setProperty('color','#f3f7f4','important');el.style.setProperty('border-color','#40584a','important')})}
function vineduInstallVisibleProfileButton(){const header=document.querySelector('header,.topbar,[class*=topbar]');if(!header||header.querySelector('[data-vinedu-profile-launch]'))return;const buttons=[...header.querySelectorAll('button')];const avatar=buttons.find(el=>/^[A-Z0-9]$/i.test(el.textContent.trim())||el.querySelector('img[alt*=profile]'))||buttons.at(-1);if(!avatar)return;const button=document.createElement('button');button.type='button';button.dataset.vineduProfileLaunch='true';button.className='vinedu-profile-launch';button.innerHTML='<span aria-hidden="true">♙</span><span>My profile</span>';button.addEventListener('click',()=>vineduOpenProfileCard());avatar.before(button)}
function vineduRepairVisibleProfileMenu(){const signout=[...document.querySelectorAll('body *')].find(el=>el.children.length===0&&/sign out|log out/i.test(el.textContent.trim()));if(!signout)return;let menu=signout.parentElement;for(let i=0;i<5&&menu?.parentElement;i++){if(/@/.test(menu.innerText||'')||/engineering student|administrator/i.test(menu.innerText||''))break;menu=menu.parentElement}if(!menu||menu.querySelector('[data-vinedu-view-profile]'))return;const row=signout.closest('button,a,[role=button]')||signout.parentElement;if(!row?.parentElement)return;const button=document.createElement('button');button.type='button';button.dataset.vineduViewProfile='true';button.className='vinedu-menu-profile-action';button.textContent='View profile';button.addEventListener('click',vineduOpenProfileCard);row.parentElement.insertBefore(button,row)}
function vineduRunGlobalPolish(){vineduForceFullDarkContrast();vineduInstallVisibleProfileButton();vineduRepairVisibleProfileMenu();new MutationObserver(()=>{vineduForceFullDarkContrast();vineduInstallVisibleProfileButton();vineduRepairVisibleProfileMenu()}).observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class','data-theme']})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',vineduRunGlobalPolish,{once:true});else vineduRunGlobalPolish();
if(!document.getElementById('vinedu-final-contrast-profile')){const style=document.createElement('style');style.id='vinedu-final-contrast-profile';style.textContent='.vinedu-profile-launch{display:inline-flex!important;align-items:center;gap:7px;height:38px;min-height:38px;padding:0 11px;border:1px solid #dce8e0;border-radius:11px;background:#f8faf8;color:#27684f;font-size:12px;font-weight:700;cursor:pointer}.vinedu-profile-launch:hover{background:#eaf4ec}.vinedu-menu-profile-action{display:block!important;width:100%!important;padding:11px 12px!important;margin:5px 0!important;border:0!important;border-radius:9px!important;background:#edf5ef!important;color:#176b4b!important;font-weight:700!important;text-align:left!important;cursor:pointer}.vinedu-menu-profile-action:hover{background:#dfefe4!important}body[data-vinedu-dark-contrast=true] .vinedu-profile-launch{background:#20392d!important;border-color:#40584a!important;color:#f1f6f2!important}body[data-vinedu-dark-contrast=true] .vinedu-menu-profile-action{background:#244a38!important;color:#f1f6f2!important}';document.head.appendChild(style)}
function vineduRepairHeaderActions(){const signout=[...document.querySelectorAll('button,a')].find(el=>/^(↪\s*)?(sign out|log out)$/i.test(el.textContent.trim()));if(signout&&!signout.parentElement.querySelector('[data-vinedu-view-profile]')){const button=document.createElement('button');button.type='button';button.dataset.vineduViewProfile='true';button.className=signout.className;button.textContent='View profile';button.style.cssText='display:block;width:100%;padding:11px 12px;margin:4px 0;border:0;border-radius:9px;background:transparent;color:#237b60;font-weight:700;text-align:left;cursor:pointer';button.addEventListener('click',()=>vineduOpenProfileCard());signout.before(button)}const header=document.querySelector('header,.topbar,[class*=topbar]');if(!header)return;const buttons=[...header.querySelectorAll('button')],avatar=buttons.find(el=>/^[A-Z0-9]$/i.test(el.textContent.trim())||el.querySelector('img[alt*=profile]'))||buttons.at(-1);let bell=buttons.find(el=>el.dataset.vineduRealBell)||buttons.find(el=>/notification/i.test((el.title||'')+' '+(el.getAttribute('aria-label')||'')))||buttons[buttons.indexOf(avatar)-1];if(!bell||!avatar)return;if(!bell.dataset.vineduRealBell){const clone=bell.cloneNode(true);clone.dataset.vineduRealBell='true';clone.setAttribute('aria-label','Notifications');clone.title='Notifications';bell.replaceWith(clone);bell=clone}if(bell.dataset.vineduBound)return;bell.dataset.vineduBound='true';const panel=document.createElement('div');panel.className='vinedu-header-popover vinedu-notice-popover';panel.hidden=true;document.body.appendChild(panel);function show(){const items=typeof vineduHeaderItems==='function'?vineduHeaderItems():[];panel.innerHTML=`<div class="vinedu-popover-title">Notifications <span>${items.length?`${items.length} updates`:'Up to date'}</span></div>${items.length?items.map(item=>`<article class="vinedu-notice"><span class="vinedu-notice-icon">${item.kind==='meeting'?'◉':item.kind==='course'?'▤':'✦'}</span><div><b>${item.title}</b><p>${item.detail}</p>${item.at?`<small>${new Date(item.at).toLocaleString()}</small>`:''}</div></article>`).join(''):'<div class="vinedu-notice-empty"><b>You’re all caught up</b><p>New course and live class updates will appear here.</p></div>'}`;const rect=bell.getBoundingClientRect();panel.style.top=`${Math.min(innerHeight-350,rect.bottom+8)}px`;panel.style.right=`${Math.max(10,innerWidth-rect.right)}px`;panel.hidden=false}bell.addEventListener('click',event=>{event.stopPropagation();show()});document.addEventListener('click',event=>{if(!panel.contains(event.target)&&!bell.contains(event.target))panel.hidden=true})}
function vineduOpenProfileCard(){const existing=document.querySelector('.vinedu-profile-view-card');if(existing){existing.remove();return}const name=db.profile?.name||db.profile?.displayName||db.name||'Student',email=db.profile?.email||db.email||'',photo=db.profile?.photo||db.profile?.avatar||db.profilePhoto;const overlay=document.createElement('div');overlay.className='vinedu-profile-view-card';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.innerHTML=`<section><button class="vinedu-profile-close" aria-label="Close">×</button>${photo?`<img src="${photo}" alt="Profile photo">`:`<div class="vinedu-profile-initial">${String(name).trim().slice(0,1).toUpperCase()}</div>`}<h2>${name}</h2><p>${email}</p><span>Engineering student</span><button class="vinedu-profile-edit">Edit profile</button></section>`;document.body.appendChild(overlay);overlay.addEventListener('click',event=>{if(event.target===overlay||event.target.closest('.vinedu-profile-close'))overlay.remove();if(event.target.closest('.vinedu-profile-edit')){overlay.remove();const settings=[...document.querySelectorAll('aside a,aside button,.sidebar a,.sidebar button')].find(el=>/^settings$/i.test(el.textContent.trim()));settings?.click()}})}
