if(!document.getElementById('vinedu-profile-repair-style')){const style=document.createElement('style');style.id='vinedu-profile-repair-style';style.textContent='.vinedu-profile-view-card{position:fixed;inset:0;z-index:20000;display:grid;place-items:center;padding:20px;background:rgba(12,34,25,.55);backdrop-filter:blur(5px)}.vinedu-profile-view-card>section{position:relative;width:min(400px,100%);padding:32px 24px 24px;border:1px solid #dfe9e2;border-radius:22px;background:#fff;text-align:center;box-shadow:0 26px 70px rgba(0,0,0,.25)}.vinedu-profile-view-card img,.vinedu-profile-initial{display:grid;width:88px;height:88px;object-fit:cover;place-items:center;margin:0 auto 12px;border:4px solid #edf5ef;border-radius:50%;background:#e3f1e7;color:#226c4f;font-size:32px;font-weight:750}.vinedu-profile-view-card h2{margin:8px 0 2px}.vinedu-profile-view-card p{margin:3px 0 12px;color:#687d73}.vinedu-profile-view-card section>span{display:inline-block;padding:6px 12px;border-radius:20px;background:#edf5ef;color:#267653;font-size:12px}.vinedu-profile-close{position:absolute;right:14px;top:12px;width:34px;height:34px;border:0;border-radius:50%;background:#f2f6f3;color:#4f675c;font-size:22px;cursor:pointer}.vinedu-profile-edit{display:block;margin:20px auto 0;padding:10px 18px;border:0;border-radius:10px;background:#237b60;color:#fff;font-weight:700;cursor:pointer}';document.head.appendChild(style)}
