function vineduInstallProfileAndBell(){const header=document.querySelector('header,.topbar,[class*=topbar]');if(!header||header.dataset.vineduProfileBell)return;let buttons=[...header.querySelectorAll('button')];if(buttons.length<2)return;let profile=buttons.find(b=>/^[A-Z0-9]$/i.test(b.textContent.trim())||b.querySelector('img[alt*=profile]'))||buttons[buttons.length-1];let bell=buttons.find(b=>/notification/i.test((b.title||'')+' '+(b.getAttribute('aria-label')||'')))||buttons[buttons.indexOf(profile)-1];if(!bell||!profile)return;header.dataset.vineduProfileBell='ready';const cleanClone=element=>{const clone=element.cloneNode(true);element.replaceWith(clone);return clone};bell=cleanClone(bell);profile=cleanClone(profile);bell.classList.add('vinedu-notification-trigger');bell.innerHTML='<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9"/><path d="M10 21h4"/></svg><i class="vinedu-notice-dot" hidden></i>';bell.setAttribute('aria-label','Notifications');bell.title='Notifications';profile.classList.add('vinedu-profile-trigger');profile.setAttribute('aria-label','Open your profile');profile.title='My profile';const notify=document.createElement('div');notify.className='vinedu-header-popover vinedu-live-notifications';notify.hidden=true;const user=document.createElement('div');user.className='vinedu-header-popover vinedu-user-menu';user.hidden=true;const detail=document.createElement('div');detail.className='vinedu-header-popover vinedu-profile-details';detail.hidden=true;document.body.append(notify,user,detail);function position(panel,button){const r=button.getBoundingClientRect();panel.style.top=`${Math.min(innerHeight-300,r.bottom+10)}px`;panel.style.right=`${Math.max(12,innerWidth-r.right)}px`;panel.hidden=false}function renderNotificationList(){const items=typeof vineduHeaderItems==='function'?vineduHeaderItems():[];const seenKey=`vinedu-notice-seen:${typeof vineduHeaderAccount==='function'?vineduHeaderAccount():'student'}`;let seen=[];try{seen=JSON.parse(localStorage.getItem(seenKey)||'[]')}catch{}const unread=items.filter(item=>!seen.includes(`${item.kind}:${item.title}:${item.at}`));bell.querySelector('.vinedu-notice-dot').hidden=!unread.length;notify.innerHTML=`<div class="vinedu-popover-title">Notifications <span>${unread.length?`${unread.length} new`:'Up to date'}</span></div>${items.length?items.map(item=>`<article class="vinedu-notice"><span class="vinedu-notice-icon">${item.kind==='meeting'?'◉':item.kind==='course'?'▤':'✦'}</span><div><b>${item.title}</b><p>${item.detail}</p>${item.at?`<small>${new Date(item.at).toLocaleString()}</small>`:''}</div></article>`).join(''):'<div class="vinedu-notice-empty"><span>✦</span><b>You’re all caught up</b><p>New courses and live class updates will appear here.</p></div>'}`;try{localStorage.setItem(seenKey,JSON.stringify(items.map(i=>`${i.kind}:${i.title}:${i.at}`).slice(-60)))}catch{}}function renderUserMenu(){const name=db.profile?.name||db.name||'Student',email=db.profile?.email||db.email||'',role=db.role==='admin'?'Administrator':'Engineering student';user.innerHTML=`<div class="vinedu-user-summary"><span class="vinedu-user-avatar">${profile.querySelector('img')?profile.querySelector('img').outerHTML:String(name).trim().slice(0,1).toUpperCase()}</span><div><b>${name}</b><small>${email}</small><span>${role}</span></div></div><button type="button" data-open-profile>View profile <span>→</span></button><button type="button" data-edit-profile>Edit profile & settings</button><button type="button" data-user-signout>↪ Sign out</button>`}function openProfile(){renderUserMenu();notify.hidden=true;detail.hidden=true;position(user,profile)}function showProfile(){const name=db.profile?.name||db.name||'Student',email=db.profile?.email||db.email||'',avatar=db.profile?.photo||db.profile?.avatar||db.profilePhoto;detail.innerHTML=`<div class="vinedu-profile-cover"><button type="button" data-profile-close aria-label="Close">×</button></div><div class="vinedu-profile-content">${avatar?`<img src="${avatar}" alt="Profile photo">`:`<span class="vinedu-user-avatar">${String(name).trim().slice(0,1).toUpperCase()}</span>`}<h2>${name}</h2><p>${email}</p><span class="vinedu-profile-role">${db.role==='admin'?'Administrator':'Engineering student'}</span><button type="button" data-edit-profile>Open profile settings</button></div>`;user.hidden=true;position(detail,profile)}bell.addEventListener('click',event=>{event.stopPropagation();user.hidden=detail.hidden=true;renderNotificationList();position(notify,bell)});profile.addEventListener('click',event=>{event.stopPropagation();notify.hidden=detail.hidden=true;openProfile()});user.addEventListener('click',event=>{const target=event.target.closest('[data-open-profile],[data-edit-profile],[data-user-signout]');if(!target)return;if(target.matches('[data-open-profile]'))showProfile();else if(target.matches('[data-edit-profile]')){const settings=[...document.querySelectorAll('aside a,aside button,.sidebar a,.sidebar button')].find(el=>/^settings$/i.test(el.textContent.trim()));if(settings)settings.click();else{const link=[...document.querySelectorAll('a,button')].find(el=>/^settings$/i.test(el.textContent.trim()));link?.click()}user.hidden=true}else{const signout=[...document.querySelectorAll('aside a,aside button,.sidebar a,.sidebar button')].find(el=>/sign out|log out/i.test(el.textContent));signout?.click()}});detail.addEventListener('click',event=>{if(event.target.closest('[data-profile-close]'))detail.hidden=true;if(event.target.closest('[data-edit-profile]')){const settings=[...document.querySelectorAll('a,button')].find(el=>/^settings$/i.test(el.textContent.trim()));settings?.click();detail.hidden=true}});document.addEventListener('click',event=>{if(!notify.contains(event.target)&&!bell.contains(event.target))notify.hidden=true;if(!user.contains(event.target)&&!profile.contains(event.target))user.hidden=true;if(!detail.contains(event.target)&&!profile.contains(event.target))detail.hidden=true});document.addEventListener('keydown',event=>{if(event.key==='Escape')notify.hidden=user.hidden=detail.hidden=true})}
