vineduResetUnverifiedStudyTime=function(){const label=[...document.querySelectorAll('body *')].find(el=>el.children.length===0&&/^study time today$/i.test(el.textContent.trim()));if(!label)return;let card=label,values=[];for(let i=0;i<9&&card;i++,card=card.parentElement){values=[...card.querySelectorAll('strong,b,h1,h2,h3,span,div,p')].filter(el=>el.children.length===0&&/^\d+\s*h(?:\s*\d+\s*m)?$|^\d+\s*m$/i.test(el.textContent.trim()));if(values.length)break}const seconds=Math.max(0,Number(window.__vineduStudySeconds)||0),mins=Math.floor(seconds/60),shown=mins>=60?`${Math.floor(mins/60)}h ${mins%60}m`:`${mins}m`;if(values.length&&values[0].textContent.trim()!==shown)values[0].textContent=shown;const note=[...card.querySelectorAll('p,small,span')].find(el=>/active study|saved on this device|no study time recorded|focused study time/i.test(el.textContent));if(note){const text=mins?'Active lesson time for this session':'No study time recorded yet';if(note.textContent.trim()!==text)note.textContent=text}};
