function vineduLiveStudyClock(){const isMaterialOpen=()=>[...document.querySelectorAll('.vinedu-study,.vinedu-long-lesson')].some(el=>el.getClientRects().length>0);let previous=Date.now();const interact=()=>window.__vineduStudyLastInput=Date.now();['pointerdown','pointermove','scroll','keydown','touchstart','click'].forEach(type=>document.addEventListener(type,interact,{passive:true}));setInterval(()=>{const now=Date.now(),delta=Math.min(2,Math.max(0,(now-previous)/1000));previous=now;if(document.visibilityState==='visible'&&(!document.hasFocus||document.hasFocus())&&isMaterialOpen()&&window.__vineduStudyLastInput&&now-window.__vineduStudyLastInput<120000)window.__vineduStudySeconds+=delta;vineduResetUnverifiedStudyTime()},1000)}
