const vineduSaveKey=(name)=>`vinedu-${name}:${vineduStudentKey()}`;function vineduReadLocal(name){try{return JSON.parse(localStorage.getItem(vineduSaveKey(name))||'[]')}catch{return []}}function vineduWriteLocal(name,value){try{localStorage.setItem(vineduSaveKey(name),JSON.stringify(value))}catch{}}
document.addEventListener('submit',event=>{const form=event.target;if(form.id!=='vinedu-book-quiz')return;const course=form.closest('.vinedu-study')?.querySelector('h2')?.textContent?.trim()||'Engineering course';const book=VINE_EDU_READING[Object.keys(VINE_EDU_READING).find(k=>course.toLowerCase().includes(k))];if(!book)return;const answers=new FormData(form),queue=vineduReadLocal('revision-queue');book.quiz.forEach((q,i)=>{const selected=answers.get(`q${i}`);if(selected!==null&&Number(selected)!==q[2])queue.unshift({course,question:q[0],answer:q[1][q[2]],explanation:q[3],at:new Date().toISOString()})});const unique=[...new Map(queue.map(item=>[`${item.course}:${item.question}`,item])).values()].slice(0,100);vineduWriteLocal('revision-queue',unique);setTimeout(vineduRenderStudyTools,0)},true);
function vineduInstallReaderTools(){document.querySelectorAll('.vinedu-study .study-chapter').forEach(chapter=>{if(chapter.querySelector('.study-bookmark'))return;const course=chapter.closest('.vinedu-study')?.querySelector('h2')?.textContent?.trim()||'';const title=chapter.querySelector('h3')?.textContent?.trim()||'';const key=`${course}:${title}`;const saved=vineduReadLocal('bookmarks').some(item=>item.key===key);const button=document.createElement('button');button.type='button';button.className='study-bookmark';button.dataset.bookmarkKey=key;button.textContent=saved?'★ Bookmarked':'☆ Bookmark section';chapter.appendChild(button)});document.querySelectorAll('.vinedu-study').forEach(reader=>{if(reader.querySelector('.study-save-highlight'))return;const button=document.createElement('button');button.type='button';button.className='study-save-highlight';button.textContent='Save selected text';button.addEventListener('click',()=>{const text=String(getSelection()?.toString()||'').trim();if(!text){button.textContent='Select a sentence first';setTimeout(()=>button.textContent='Save selected text',1800);return}const course=reader.querySelector('h2')?.textContent?.trim()||'Course notes';const highlights=vineduReadLocal('highlights');highlights.unshift({course,text:text.slice(0,600),at:new Date().toISOString()});vineduWriteLocal('highlights',highlights.slice(0,100));button.textContent='✓ Saved to My notes';setTimeout(()=>button.textContent='Save selected text',1800)});reader.querySelector('.study-head')?.appendChild(button)})}
document.addEventListener('click',event=>{const button=event.target.closest('.study-bookmark');if(!button)return;const key=button.dataset.bookmarkKey;let items=vineduReadLocal('bookmarks');if(items.some(item=>item.key===key)){items=items.filter(item=>item.key!==key);button.textContent='☆ Bookmark section'}else{items.unshift({key,course:key.split(':')[0],section:key.split(':').slice(1).join(':'),at:new Date().toISOString()});button.textContent='★ Bookmarked'}vineduWriteLocal('bookmarks',items.slice(0,100));vineduRenderStudyTools()});
function vineduRenderStudyTools(){const grid=document.querySelector('.vinedu-dashboard-addons .vinedu-dashboard-grid');if(!grid)return;grid.querySelectorAll('.vinedu-revision-panel,.vinedu-bookmark-panel').forEach(el=>el.remove());const revisions=vineduReadLocal('revision-queue'),bookmarks=vineduReadLocal('bookmarks'),highlights=vineduReadLocal('highlights');const panel=(cls,title,eyebrow,body)=>{const el=document.createElement('article');el.className=`vinedu-dash-panel ${cls}`;el.innerHTML=`<div class="vinedu-panel-heading"><div><span class="vinedu-eyebrow">${eyebrow}</span><h2>${title}</h2></div><span class="vinedu-week-total">${cls.includes('revision')?revisions.length:bookmarks.length+highlights.length} saved</span></div>${body}`;grid.appendChild(el)};const revBody=revisions.length?`<div class="vinedu-revision-list">${revisions.slice(0,4).map((item,i)=>`<details><summary>${item.question}</summary><p><b>Answer:</b> ${item.answer}</p><p>${item.explanation}</p><small>${item.course}</small><button type="button" data-revision-done="${i}">Reviewed</button></details>`).join('')}</div>`:'<p class="vinedu-panel-note">Missed quiz questions will appear here for revision.</p>';panel('vinedu-revision-panel','Smart revision','REVISIT WHAT YOU MISSED',revBody);const saved=[...bookmarks.slice(0,3).map(item=>({label:`${item.course} · ${item.section}`,kind:'Bookmark'})),...highlights.slice(0,3).map(item=>({label:`${item.course} · “${item.text.slice(0,70)}${item.text.length>70?'…':''}”`,kind:'Highlight'}))];const savedBody=saved.length?`<div class="vinedu-saved-list">${saved.map(item=>`<div><span>${item.kind}</span><p>${item.label}</p></div>`).join('')}</div>`:'<p class="vinedu-panel-note">Bookmark a lesson section or save selected text while reading.</p>';panel('vinedu-bookmark-panel','Saved notes','YOUR STUDY LIBRARY',savedBody)}
