function vineduAddCertificates(){document.querySelectorAll('article,[class*=course-card]').forEach(card=>{if(card.querySelector('.vinedu-certificate-button')||card.closest('.vinedu-dashboard-addons'))return;const id=card.dataset.course;if(!id)return;const course=(db.courses||[]).find(item=>String(item.id)===String(id));if(!course||typeof pct!=='function'||pct(course)<100)return;const button=document.createElement('button');button.type='button';button.className='vinedu-certificate-button';button.textContent='Download certificate';button.addEventListener('click',()=>{const name=db.profile?.name||db.name||'Student',escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const win=window.open('','_blank');if(!win)return;win.document.write(`<!doctype html><html><head><title>Certificate · ${escape(course.title)}</title><style>body{font-family:Georgia,serif;background:#f5f8f5;padding:7vh 5vw;color:#173b32}.certificate{max-width:950px;margin:auto;padding:70px;border:12px double #2d8062;background:white;text-align:center}.brand{letter-spacing:.2em;color:#2d8062}.name{font-size:48px;border-bottom:1px solid #abc6b6;padding:18px}.course{font-size:32px}.date{margin-top:40px;color:#526c62}@media print{body{background:white;padding:0}.certificate{max-width:none;border:10px double #2d8062}}</style></head><body><main class="certificate"><p class="brand">VINEDU · ENGINEERING LEARNING</p><h1>Certificate of Completion</h1><p>This certificate is presented to</p><div class="name">${escape(name)}</div><p>for successfully completing</p><h2 class="course">${escape(course.title)}</h2><p class="date">Completed on ${new Date().toLocaleDateString()}</p><button onclick="print()">Print / Save as PDF</button></main></body></html>`);win.document.close()});card.appendChild(button)})}
function vineduWatchStudyFeatures(){if(!document.body)return;vineduInstallReaderTools();if(document.querySelector('.vinedu-dashboard-addons .vinedu-dashboard-grid')&&!document.querySelector('.vinedu-revision-panel'))vineduRenderStudyTools();vineduAddCertificates();new MutationObserver(()=>{vineduInstallReaderTools();if(document.querySelector('.vinedu-dashboard-addons .vinedu-dashboard-grid')&&!document.querySelector('.vinedu-revision-panel'))vineduRenderStudyTools();vineduAddCertificates()}).observe(document.body,{childList:true,subtree:true})}
