if(!document.getElementById('vinedu-study-tools-style')){const style=document.createElement('style');style.id='vinedu-study-tools-style';style.textContent='.study-bookmark,.study-save-highlight,.vinedu-certificate-button{display:inline-flex;align-items:center;gap:7px;margin:8px 8px 0 0;padding:8px 12px;border:1px solid #d8e7dc;border-radius:10px;background:#f3f8f4;color:#226b4f;font-size:12px;font-weight:650;cursor:pointer}.study-save-highlight{margin:0}.vinedu-revision-list details{padding:11px 0;border-bottom:1px solid #e4ece6}.vinedu-revision-list summary{cursor:pointer;font-size:13px;font-weight:650;color:#254a39}.vinedu-revision-list p{font-size:12px;margin:8px 0}.vinedu-revision-list button{padding:5px 9px;border:0;border-radius:8px;background:#eaf4ec;color:#246c50;cursor:pointer}.vinedu-saved-list>div{padding:9px 0;border-bottom:1px solid #e4ece6}.vinedu-saved-list span{font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#31805f;font-weight:700}.vinedu-saved-list p{font-size:12px;margin:3px 0}.vinedu-certificate-button{margin-top:14px;background:#237b60;color:#fff;border-color:#237b60}@media print{.study-bookmark,.study-save-highlight,.vinedu-certificate-button{display:none!important}}';document.head.appendChild(style)}
function vineduPlaceExtrasUnderGreeting(){const panel=document.querySelector('.vinedu-dashboard-addons');if(!panel)return;const greeting=[...document.querySelectorAll('h1,h2')].find(el=>/^good (morning|afternoon|evening)\b/i.test(el.textContent.trim()));if(!greeting)return;const label=[...document.querySelectorAll('body *')].find(el=>el.children.length===0&&/^enrolled courses$/i.test(el.textContent.trim()));if(!label)return;let stats=label;for(let i=0;i<8&&stats.parentElement;i++){stats=stats.parentElement;const count=[...stats.querySelectorAll('body *')].filter(el=>el.children.length===0&&/^(enrolled courses|learning progress|study time today|quiz attempts)$/i.test(el.textContent.trim())).length;if(count>=3)break}if(stats.parentElement&&panel.nextElementSibling!==stats)stats.parentElement.insertBefore(panel,stats)}
