function vineduResetUnverifiedStudyTime(){const values=[...document.querySelectorAll('h1,h2,h3,h4,strong,b,span,small,div,p')].filter(el=>el.children.length===0&&/^\d+\s*h(?:\s*\d+\s*m)?$|^\d+\s*m$/i.test(el.textContent.trim()));for(const value of values){let card=value,found=false;for(let i=0;i<8&&card;i++,card=card.parentElement){if(/study time today/i.test(card.innerText||'')){found=true;break}}if(!found)continue;if(value.textContent.trim()!=='0m')value.textContent='0m';const note=[...card.querySelectorAll('p,small,span')].find(el=>/active study|saved on this device/i.test(el.textContent));if(note&&/active study/i.test(note.textContent))note.textContent='No study time recorded yet'}}
