function vineduHeaderItems(){const raw=Array.isArray(db.notifications)?db.notifications:[];const courses=Array.isArray(db.courses)?db.courses:[];const meetings=[...(Array.isArray(db.sessions)?db.sessions:[]),...(Array.isArray(db.meetings)?db.meetings:[]),...(Array.isArray(db.liveClasses)?db.liveClasses:[])];const notices=raw.map(item=>({kind:item.type||'update',title:item.title||item.message||'Learning space update',detail:item.body||item.description||'',at:item.createdAt||item.created_at||item.date||''}));courses.filter(c=>c&&(c.createdBy||c.created_at||c.createdAt||c.isCustom)).forEach(c=>notices.push({kind:'course',title:`New course: ${c.title||c.name||'Course added'}`,detail:c.description||'A course was added to the learning space.',at:c.createdAt||c.created_at||''}));meetings.forEach(m=>notices.push({kind:'meeting',title:m.title||m.name||'Live class',detail:m.startAt||m.start_at||m.date||'Upcoming session',at:m.createdAt||m.created_at||m.startAt||m.start_at||m.date||''}));return notices.slice(-20).reverse()}
function vineduSetupHeaderMenus(){const header=document.querySelector('header,.topbar,[class*=topbar]');if(!header||header.dataset.vineduMenus)return;const buttons=[...header.querySelectorAll('button')];if(buttons.length<2)return;header.dataset.vineduMenus='ready';const themeButton=buttons.find(b=>/theme|dark|light/i.test((b.title||'')+' '+(b.getAttribute('aria-label')||''))||/[☾☽🌙]/.test(b.textContent))||buttons[Math.max(0,buttons.length-3)];const bellButton=buttons.find(b=>/notification/i.test((b.title||'')+' '+(b.getAttribute('aria-label')||''))||/[♧♙🔔]/.test(b.textContent))||buttons[Math.max(0,buttons.length-2)];function makePanel(className){const panel=document.createElement('div');panel.className=className;panel.hidden=true;document.body.appendChild(panel);return panel}const themePanel=makePanel('vinedu-header-popover vinedu-theme-popover');themePanel.innerHTML='<div class="vinedu-popover-title">Appearance</div><p>Choose how Vinedu looks on this device.</p><div class="vinedu-theme-options"><button data-mode="light">☀️ <span>Light</span></button><button data-mode="dark">☾ <span>Dark</span></button><button data-mode="system">◐ <span>System</span></button></div>';const noticePanel=makePanel('vinedu-header-popover vinedu-notice-popover');function renderNotices(){const items=vineduHeaderItems();const key=`vinedu-notice-seen:${vineduHeaderAccount()}`;let seen=[];try{seen=JSON.parse(localStorage.getItem(key)||'[]')}catch{}const count=items.filter(item=>!seen.includes(`${item.kind}:${item.title}:${item.at}`)).length;bellButton?.setAttribute('aria-label',`Notifications${count?`, ${count} new`:''}`);bellButton?.setAttribute('title',count?`${count} new notifications`:'Notifications');noticePanel.innerHTML=`<div class="vinedu-popover-title">Notifications <span>${count?`${count} new`:'Up to date'}</span></div>${items.length?items.map(item=>`<article class="vinedu-notice"><span class="vinedu-notice-icon">${item.kind==='meeting'?'◉':item.kind==='course'?'▤':'✦'}</span><div><b>${item.title}</b><p>${item.detail}</p>${item.at?`<small>${new Date(item.at).toLocaleString()}</small>`:''}</div></article>`).join(''):'<div class="vinedu-notice-empty"><span>✦</span><b>You’re all caught up</b><p>New courses and live class updates will appear here when available.</p></div>'}`;try{localStorage.setItem(key,JSON.stringify(items.map(item=>`${item.kind}:${item.title}:${item.at}`).slice(-50)))}catch{}}
function openAt(panel,button){const box=button.getBoundingClientRect();panel.style.top=`${Math.min(innerHeight-360,box.bottom+10)}px`;panel.style.right=`${Math.max(12,innerWidth-box.right)}px`;panel.hidden=false}themeButton?.setAttribute('aria-label','Theme options');themeButton?.setAttribute('title','Theme options');themeButton?.addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();noticePanel.hidden=true;openAt(themePanel,themeButton)},{capture:true});bellButton?.addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();themePanel.hidden=true;renderNotices();openAt(noticePanel,bellButton)},{capture:true});themePanel.addEventListener('click',event=>{const button=event.target.closest('[data-mode]');if(!button)return;vineduApplyTheme(button.dataset.mode);themePanel.querySelectorAll('[data-mode]').forEach(item=>item.classList.toggle('selected',item===button));themePanel.hidden=true});document.addEventListener('click',event=>{if(!themePanel.contains(event.target)&&!themeButton?.contains(event.target))themePanel.hidden=true;if(!noticePanel.contains(event.target)&&!bellButton?.contains(event.target))noticePanel.hidden=true});document.addEventListener('keydown',event=>{if(event.key==='Escape'){themePanel.hidden=true;noticePanel.hidden=true}});const saved=localStorage.getItem('vinedu-theme-choice');if(saved)vineduApplyTheme(saved);else{document.body.dataset.theme=document.body.classList.contains('dark')?'dark':'light'}const popObserver=new MutationObserver(()=>{const menu=[...document.querySelectorAll('[role=menu],[class*=profile-menu],[class*=dropdown],[class*=popover]')].find(el=>/sign out|log out/i.test(el.textContent)&&!el.querySelector('.vinedu-profile-link'));if(menu){const button=document.createElement('button');button.type='button';button.className='vinedu-profile-link';button.innerHTML='<span aria-hidden="true">♙</span> My profile';button.addEventListener('click',()=>{const settings=[...document.querySelectorAll('a,button')].find(el=>/^settings$/i.test(el.textContent.trim()));settings?.click()});const signout=[...menu.querySelectorAll('button,a')].find(el=>/sign out|log out/i.test(el.textContent));if(signout)signout.before(button);else menu.appendChild(button)}});popObserver.observe(document.body,{childList:true,subtree:true})}
function vineduDirectorySnapshot(){const courses=(Array.isArray(db.courses)?db.courses:[]).map(c=>`course:${c.id||c.slug||c.title||c.name}`);const meetings=[...(Array.isArray(db.sessions)?db.sessions:[]),...(Array.isArray(db.meetings)?db.meetings:[]),...(Array.isArray(db.liveClasses)?db.liveClasses:[])].map(m=>`meeting:${m.id||m.title||m.name}:${m.startAt||m.start_at||m.date||''}`);return [...courses,...meetings]}
