const VINE_DASHBOARD_LOG_KEY='vinedu-dashboard-events-v1';
function vineduStudentKey(){return String(db?.profile?.email||db?.email||db?.user?.email||'student').trim().toLowerCase()}
function vineduReadEvents(){try{return JSON.parse(localStorage.getItem(`${VINE_DASHBOARD_LOG_KEY}:${vineduStudentKey()}`)||'[]')}catch{return []}}
function vineduLogEvent(kind,label){const events=vineduReadEvents();events.push({kind,label:String(label||'Learning activity').slice(0,140),at:new Date().toISOString()});try{localStorage.setItem(`${VINE_DASHBOARD_LOG_KEY}:${vineduStudentKey()}`,JSON.stringify(events.slice(-500)))}catch{}vineduRenderDashboardAddons()}
function vineduRenderDashboardAddons(){const greeting=[...document.querySelectorAll('h1,h2')].find(el=>/^good morning\b/i.test(el.textContent.trim()));if(!greeting)return;const main=greeting.closest('main')||document.querySelector('main')||document.body;if(main.querySelector('.vinedu-dashboard-addons'))return;const events=vineduReadEvents();const today=new Date();const days=Array.from({length:7},(_,i)=>{const date=new Date(today);date.setDate(today.getDate()-6+i);const key=date.toDateString();return{date,key,count:events.filter(e=>new Date(e.at).toDateString()===key).length}});const max=Math.max(1,...days.map(d=>d.count));const dayId=today.toISOString().slice(0,10);const planKey=`vinedu-daily-plan:${vineduStudentKey()}:${dayId}`;let checked=[];try{checked=JSON.parse(localStorage.getItem(planKey)||'[]')}catch{}const completed=Array.isArray(db.completed)?db.completed.length:0;const badges=[{n:1,t:'First lesson',i:'✦'},{n:5,t:'Five lessons',i:'⚡'},{n:10,t:'10 lessons',i:'◆'}];const weekMarkup=days.map(d=>`<div class="vinedu-week-day"><span class="vinedu-week-bar" style="--bar:${Math.max(8,Math.round(d.count/max*100))}%" title="${d.count} learning activities"></span><small>${d.date.toLocaleDateString(undefined,{weekday:'short'}).slice(0,2)}</small></div>`).join('');const tasks=['Study one lesson','Try a 5-question quiz','Review your notes'];const badgeMarkup=badges.map(b=>`<div class="vinedu-badge ${completed>=b.n?'is-earned':'is-locked'}"><span>${b.i}</span><div><b>${b.t}</b><small>${completed>=b.n?'Unlocked':`${completed}/${b.n} lessons`}</small></div></div>`).join('');const panel=document.createElement('section');panel.className='vinedu-dashboard-addons';panel.innerHTML=`<div class="vinedu-dashboard-grid"><article class="vinedu-dash-panel"><div class="vinedu-panel-heading"><div><span class="vinedu-eyebrow">YOUR ACTIVITY</span><h2>This week</h2></div><span class="vinedu-week-total">${days.reduce((n,d)=>n+d.count,0)} activities</span></div><div class="vinedu-week-chart">${weekMarkup}</div><p class="vinedu-panel-note">Lesson completions and quizzes are counted from today onward.</p></article><article class="vinedu-dash-panel"><div class="vinedu-panel-heading"><div><span class="vinedu-eyebrow">A SIMPLE PLAN</span><h2>Today’s study plan</h2></div><span class="vinedu-plan-count">${checked.length}/3</span></div><div class="vinedu-plan-list">${tasks.map((task,i)=>`<label><input type="checkbox" data-vinedu-plan="${i}" ${checked.includes(i)?'checked':''}><span>${task}</span></label>`).join('')}</div><p class="vinedu-panel-note">Small goals make it easier to keep a steady routine.</p></article><article class="vinedu-dash-panel"><div class="vinedu-panel-heading"><div><span class="vinedu-eyebrow">MILESTONES</span><h2>Your achievements</h2></div><span class="vinedu-badge-count">${badges.filter(b=>completed>=b.n).length} earned</span></div><div class="vinedu-badge-list">${badgeMarkup}</div></article></div>`;const continueHeading=[...main.querySelectorAll('h2,h3')].find(el=>/continue learning/i.test(el.textContent));const insertion=continueHeading?.closest('section')||continueHeading?.parentElement; if(insertion?.parentElement)insertion.parentElement.insertBefore(panel,insertion);else main.appendChild(panel);panel.addEventListener('change',e=>{if(!e.target.matches('[data-vinedu-plan]'))return;const value=Number(e.target.dataset.vineduPlan);const list=[...panel.querySelectorAll('[data-vinedu-plan]:checked')].map(item=>Number(item.dataset.vineduPlan));try{localStorage.setItem(planKey,JSON.stringify(list))}catch{}panel.querySelector('.vinedu-plan-count').textContent=`${list.length}/3`});const cards=[...main.querySelectorAll('article,[class*=course-card]')];cards.forEach(card=>{if(card.closest('.vinedu-dashboard-addons')||card.querySelector('.vinedu-course-cover'))return;const title=card.querySelector('h2,h3,h4,strong')?.textContent?.trim();if(!title)return;const initials=title.split(/\s+/).slice(0,2).map(word=>word[0]).join('').toUpperCase();const cover=document.createElement('div');cover.className='vinedu-course-cover';cover.innerHTML=`<span>${initials}</span><small>ENGINEERING LEARNING PATH</small>`;card.prepend(cover)});}
