function vineduSetupSidebarFinder(){const sidebar=document.querySelector('aside,.sidebar,[class*=sidebar]');if(!sidebar||sidebar.querySelector('.vinedu-nav-finder'))return;const nav=sidebar.querySelector('nav');const box=document.createElement('div');box.className='vinedu-nav-finder';box.innerHTML='<span aria-hidden="true">⌕</span><input type="search" aria-label="Find a page" placeholder="Find a page…"><button type="button" aria-label="Clear page search" title="Clear">×</button><p class="vinedu-nav-empty" hidden>No matching page</p>';const input=box.querySelector('input'),clear=box.querySelector('button'),items=[...(nav||sidebar).querySelectorAll('a,button')].filter(el=>!el.closest('.vinedu-nav-finder'));const reset=()=>{input.value='';items.forEach(item=>item.hidden=false);box.querySelector('.vinedu-nav-empty').hidden=true};input.addEventListener('input',()=>{const q=input.value.trim().toLowerCase();let count=0;items.forEach(item=>{const match=!q||item.textContent.toLowerCase().includes(q);item.hidden=!match;if(match)count++});box.querySelector('.vinedu-nav-empty').hidden=count>0});clear.addEventListener('click',reset);input.addEventListener('keydown',e=>{if(e.key==='Escape'){reset();input.blur()}if(e.key==='ArrowDown'){e.preventDefault();items.find(item=>!item.hidden)?.focus()}});if(nav)nav.parentElement.insertBefore(box,nav);else sidebar.insertBefore(box,sidebar.firstChild);}
